int insideCount = 0;
std::mt19937 rng(std::random_device{}());
std::uniform_real_distribution<double> dist(-1.0, 1.0);
const double farScale = 1e6; // sufficiently large distance

for (int i = 0; i < numberOfChecks; ++i) {
    double dx = dist(rng);
    double dy = dist(rng);
    double dz = dist(rng);
    double norm = std::sqrt(dx * dx + dy * dy + dz * dz);
    if (norm == 0.0) {
        --i; // retry this iteration
        continue;
    }
    dx /= norm;
    dy /= norm;
    dz /= norm;

    Point3d farPoint(
        p.x() + dx * farScale,
        p.y() + dy * farScale,
        p.z() + dz * farScale
    );

    int intersected = numberIntersectedPrimitives(p, farPoint);
    if (intersected % 2 == 1) {
        ++insideCount;
    }
}
return insideCount > numberOfChecks / 2;

